func TestTmpScheme(t *testing.T) {
	c := new(context)
	req := httptest.NewRequest(http.MethodGet, "/", nil)
	req.Header.Set(HeaderXForwardedProto, "ftp")
	req.Header.Set(HeaderXUrlScheme, "https")
